-- Ejecutar desde la raíz del repo con SQLite CLI:
-- sqlite3 -readonly -bail data/gold/ufo_gold.db < docs/auditoria-brechas-gold.sql
-- Las consultas solo leen datos. N cuenta informes, salvo verificaciones rotuladas con otro grano.
.bail on
.headers off
.mode csv
PRAGMA query_only=ON;

-- Cobertura de cada propuesta, en el orden de la tabla del informe.
.print propuesta,informes
SELECT 'P01' AS propuesta, (SELECT COUNT(*) FROM fact_report) AS informes;
SELECT 'P02' AS propuesta, (SELECT COUNT(*) FROM fact_report) AS informes;
SELECT 'P03' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2023) AS informes;
SELECT 'P04' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2023 AND source_code='UFO-search') AS informes;
SELECT 'P05' AS propuesta, (SELECT COUNT(*) FROM fact_report) AS informes;
SELECT 'P06' AS propuesta, (SELECT COUNT(*) FROM fact_report) AS informes;
SELECT 'P07' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE has_description IN (0,1)) AS informes;
SELECT 'P08' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE has_description IN (0,1) AND has_media IN (0,1)) AS informes;
SELECT 'P09' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_country=1) AS informes;
SELECT 'P10' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0) AS informes;
SELECT 'P11' AS propuesta, (SELECT COUNT(*) FROM fact_report) AS informes;
SELECT 'P12' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_map=0 OR usable_for_country=0) AS informes;
SELECT 'P13' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE evidence_year_min IS NOT NULL AND evidence_year_max >= evidence_year_min) AS informes;
SELECT 'P14' AS propuesta, (SELECT COUNT(*) FROM (SELECT COUNT(*) OVER(PARTITION BY source_code,source_record_id) AS n FROM fact_report WHERE TRIM(source_record_id)<>'') WHERE n>1) AS informes;
SELECT 'P15' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0 AND shape_code <> 'Unknown') AS informes;
SELECT 'P16' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0 AND usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2023) AS informes;
SELECT 'P17' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0) AS informes;
SELECT 'P18' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 3600) AS informes;
SELECT 'P19' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE num_witnesses >= 0) AS informes;
SELECT 'P20' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0 AND num_witnesses > 0) AS informes;
SELECT 'P21' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0 AND movement_type IS NOT NULL) AS informes;
SELECT 'P22' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE shape_code <> 'Unknown' AND movement_type IS NOT NULL AND has_description IN (0,1)) AS informes;
SELECT 'P23' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE shape_code <> 'Unknown' AND color_family IS NOT NULL AND source_code='UFOCAT') AS informes;
SELECT 'P24' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE hynek IS NOT NULL AND usable_for_map=1 AND usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2023) AS informes;
SELECT 'P25' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_month_analysis=1 AND usable_for_hour_analysis=1) AS informes;
SELECT 'P26' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_day_analysis=1 AND event_date BETWEEN date('1990-01-01','-14 days') AND date('2022-12-31','+14 days')) AS informes;
SELECT 'P27' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_month_analysis=1 AND event_year BETWEEN 1990 AND 2022) AS informes;
SELECT 'P28' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_calendar=1 AND decade IN (2000,2010)) AS informes;
SELECT 'P29' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_day_analysis=1 AND event_date BETWEEN '1990-01-01' AND '2022-12-31') AS informes;
SELECT 'P30' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_map=1 AND usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2023) AS informes;
SELECT 'P31' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_country=1 AND usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2022) AS informes;
SELECT 'P32' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_map=1) AS informes;
SELECT 'P33' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_calendar=1 AND usable_for_country=1 AND usable_for_map=1 AND country_iso2='US' AND decade IN (2000,2010)) AS informes;
SELECT 'P34' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_map=1) AS informes;
SELECT 'P35' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_map=1 AND usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2019) AS informes;
SELECT 'P36' AS propuesta, (SELECT COALESCE(SUM(n),0) FROM (SELECT COUNT(*) n FROM fact_report WHERE usable_for_map=1 AND usable_for_day_analysis=1 GROUP BY cell1_lat, cell1_lng, date(event_date, '-6 days', 'weekday 1') HAVING COUNT(*)>=4)) AS informes;
SELECT 'P37' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_map=1 AND usable_for_day_analysis=1) AS informes;
SELECT 'P38' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0 AND shape_code <> 'Unknown' AND usable_for_map=1 AND usable_for_country=1 AND country_iso2='US') AS informes;
SELECT 'P39' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_nuclear_proximity=1 AND usable_for_country=1) AS informes;
SELECT 'P40' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_nuclear_proximity=1 AND nuclear_distance_km IS NOT NULL) AS informes;
SELECT 'P41' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_nuclear_proximity=1 AND usable_for_country=1 AND usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2023 AND country_iso2 IN ('US','CA')) AS informes;
SELECT 'P42' AS propuesta, (SELECT COUNT(*) FROM fact_report r JOIN dim_nuclear_facility g USING(nearest_facility_key) WHERE usable_for_nuclear_proximity=1 AND nuclear_distance_km < 500) AS informes;
SELECT 'P43' AS propuesta, (SELECT COUNT(*) FROM fact_report r JOIN dim_nuclear_facility g USING(nearest_facility_key) WHERE usable_for_nuclear_proximity=1) AS informes;
SELECT 'P44' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_calendar=1 AND source_code='UFOCAT') AS informes;
SELECT 'P45' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE has_pending_candidate=1 AND pending_pair_count>0) AS informes;
SELECT 'P46' AS propuesta, (SELECT SUM(member_count) FROM fact_event) AS informes;
SELECT 'P47' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_country=1) AS informes;
SELECT 'P48' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE origin_code IS NOT NULL) AS informes;
SELECT 'P49' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE usable_for_country=1 AND shape_code <> 'Unknown' AND source_code='UFOCAT') AS informes;
SELECT 'P50' AS propuesta, (SELECT COUNT(*) FROM report_model_output) AS informes;
SELECT 'P51' AS propuesta, (SELECT COUNT(*) FROM report_model_output WHERE hoax_likelihood IS NOT NULL) AS informes;
SELECT 'P52' AS propuesta, (SELECT COUNT(*) FROM report_model_output WHERE vader_compound IS NOT NULL AND roberta_sentiment IS NOT NULL) AS informes;
SELECT 'P53' AS propuesta, (SELECT COUNT(*) FROM report_model_output WHERE sentiment_score IS NOT NULL) AS informes;
SELECT 'P54' AS propuesta, (SELECT COUNT(*) FROM report_model_output WHERE emotion_28_dominant IS NOT NULL AND emotion_7_dominant IS NOT NULL) AS informes;
SELECT 'P55' AS propuesta, (SELECT COUNT(*) FROM report_model_output WHERE quality_score IS NOT NULL AND richness_score IS NOT NULL) AS informes;
SELECT 'P56' AS propuesta, (SELECT COUNT(*) FROM report_model_output m JOIN fact_report r USING(report_id) WHERE m.richness_score IS NOT NULL AND r.has_media IN (0,1)) AS informes;
SELECT 'P57' AS propuesta, (SELECT COUNT(*) FROM report_model_output WHERE usable_for_calendar=1 AND event_year BETWEEN 1940 AND 2023 AND sentiment_score IS NOT NULL) AS informes;
SELECT 'P58' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE report_id IN (8137,8138)) AS informes;
SELECT 'P59' AS propuesta, (SELECT COUNT(*) FROM fact_report WHERE duration_seconds > 0 AND num_witnesses > 0) AS informes;
.headers on

-- Reconciliación por fuente. Cada fila tiene grano informe.
SELECT source_code, COUNT(*) AS informes, COUNT(origin_code) AS origen, SUM(usable_for_calendar) AS anio,
       SUM(usable_for_month_analysis) AS mes, SUM(usable_for_day_analysis) AS dia,
       SUM(usable_for_hour_analysis) AS hora, SUM(usable_for_hour_analysis*usable_for_day_analysis) AS dia_hora,
       SUM(usable_for_map) AS mapa, SUM(usable_for_country) AS pais,
       SUM(usable_for_nuclear_proximity) AS proximidad, SUM(uses_external_evidence) AS evidencia_externa,
       SUM(usable_for_country*usable_for_day_analysis*usable_for_map) AS pais_dia_mapa,
       SUM(usable_for_map=1 AND usable_for_country=0) AS mapa_sin_pais,
       SUM(day_placeholder_risk=1 OR month_placeholder_risk=1) AS riesgo_dia_o_mes,
       COUNT(shape_code) AS forma_no_nula, SUM(COALESCE(shape_code='Unknown',0)) AS forma_unknown,
       COUNT(hynek) AS hynek, COUNT(color_code) AS color, COUNT(movement_type) AS movimiento,
       COUNT(duration_seconds) AS duracion, SUM(COALESCE(duration_seconds=0,0)) AS duracion_cero,
       COUNT(num_witnesses) AS testigos, SUM(COALESCE(num_witnesses=0,0)) AS testigos_cero,
       SUM(has_description) AS descripcion, SUM(has_media) AS medios,
       SUM(in_confirmed_group) AS confirmados, SUM(has_pending_candidate) AS marcados
FROM fact_report GROUP BY source_code ORDER BY source_code;

SELECT source_code, COUNT(*) AS informes, COUNT(sentiment_score) AS sentimiento, COUNT(vader_compound) AS vader,
       COUNT(roberta_sentiment) AS roberta, COUNT(emotion_7_dominant) AS em7, COUNT(emotion_28_dominant) AS em28,
       COUNT(emotion_28_group) AS grupo_em28, COUNT(hoax_likelihood) AS indicador_heredado,
       COUNT(quality_score) AS calidad_heredada, COUNT(richness_score) AS riqueza_heredada
FROM report_model_output GROUP BY source_code ORDER BY source_code;

SELECT COUNT(*) AS informes_miembros, COUNT(DISTINCT canonical_event_id) AS grupos, COUNT(DISTINCT source_code) AS fuentes,
       MIN(source_code) AS fuente FROM event_report;
SELECT SUM(in_confirmed_group AND has_pending_candidate) AS confirmados_con_pendientes,
       SUM(pending_pair_count) AS incidencias_de_pares, SUM(usable_for_day_analysis*usable_for_map) AS dia_y_mapa,
       SUM(usable_for_map<>usable_for_nuclear_proximity) AS diferencia_entre_elegibilidades_geograficas
FROM fact_report;
SELECT COUNT(*) AS informes, COUNT(DISTINCT f.lat||'/'||f.lng) AS coordenadas_conjuntas
FROM fact_report f JOIN dim_nuclear_facility g USING(nearest_facility_key)
WHERE f.usable_for_nuclear_proximity=1;
SELECT facility_types, COUNT(*) AS instalaciones, SUM(nearest_reports) AS informes
FROM dim_nuclear_facility GROUP BY facility_types ORDER BY 1;
SELECT calendar_precision,date_status,date_certainty,COUNT(*) AS informes FROM fact_report GROUP BY 1,2,3;
SELECT COUNT(*) AS informes, SUM(COALESCE(a.report_id IS NULL, 0)) AS sin_salida
FROM fact_report r LEFT JOIN report_model_output a USING(report_id);

-- Tres ejemplos de agregados propuestos, con bases explícitas.
SELECT source_code, ROUND(100.0 * SUM(usable_for_country*usable_for_day_analysis*usable_for_map)
                          / COUNT(*),2) AS porcentaje_pais_dia_mapa, COUNT(*) AS base_informes
FROM fact_report GROUP BY source_code;
WITH datos AS (
  SELECT source_code, duration_seconds, ROW_NUMBER() OVER(PARTITION BY source_code ORDER BY duration_seconds) AS k,
         COUNT(*) OVER(PARTITION BY source_code) AS n
  FROM fact_report WHERE duration_seconds>0
)
SELECT source_code, AVG(duration_seconds) AS mediana_segundos, MAX(n) AS base_informes
FROM datos WHERE k IN ((n+1)/2,(n+2)/2) GROUP BY source_code;
SELECT country_iso2, ROUND(100.0 * SUM(nuclear_distance_km<10) / COUNT(*),2) AS porcentaje_bajo_10km,
       COUNT(*) AS base_informes
FROM fact_report WHERE usable_for_country=1 AND usable_for_nuclear_proximity=1
GROUP BY country_iso2 ORDER BY base_informes DESC;

