-- La copia Silver local corresponde al manifiesto de la copia Gold solicitada.
ATTACH DATABASE 'file:data/silver/ufo.db?mode=ro' AS silver;

-- Intersección ID a ID y granularidad de las tablas de evidencia.
SELECT COUNT(*) AS informes_silver, COUNT(g.report_id) AS ids_en_gold,
       COUNT(CASE WHEN s.event_year IS NOT NULL AND g.event_year IS NULL THEN 1 END) AS anio_silver_sin_anio_gold,
       COUNT(CASE WHEN s.date_event IS NOT NULL AND LENGTH(s.date_event)>=10 AND g.event_date IS NULL THEN 1 END) AS fecha_silver_con_dia_sin_dia_gold,
       COUNT(CASE WHEN s.datetime_precision IN ('minute','second','fractional_second')
                    AND g.event_hour IS NULL THEN 1 END) AS reloj_de_minuto_o_mejor_sin_hora_gold,
       COUNT(CASE WHEN s.lat IS NOT NULL AND s.lng IS NOT NULL AND g.lat IS NULL THEN 1 END) AS par_silver_sin_mapa_gold,
       COUNT(l.city) AS informes_vinculados_a_ciudad_no_nula,
       COUNT(l.state) AS informes_vinculados_a_estado_no_nulo
FROM silver.sighting s LEFT JOIN fact_report g ON g.report_id=s.id
LEFT JOIN silver.location l ON l.id=s.location_id;

SELECT decision, COUNT(*) AS filas_de_pares FROM silver.duplicate_resolution GROUP BY decision ORDER BY 1;
SELECT match_status, COUNT(*) AS informes FROM silver.event_membership GROUP BY match_status ORDER BY 1;
SELECT sd.name AS base_silver, COUNT(s.id) AS informes
FROM silver.source_database sd LEFT JOIN silver.sighting s ON s.source_db_id=sd.id GROUP BY sd.id ORDER BY sd.id;
SELECT o.name AS origen_silver, COUNT(s.id) AS informes
FROM silver.source_origin o LEFT JOIN silver.sighting s ON s.origin_id=o.id
WHERE NOT EXISTS (SELECT 1 FROM dim_origin g WHERE g.origin_code=o.name) GROUP BY o.id ORDER BY o.id;
SELECT f.facility_type, COUNT(*) AS instalaciones_fuera_de_la_regla
FROM silver.facility f
WHERE f.facility_type NOT IN ('military_base','national_lab','nuclear_test_site','test_range','nuclear_base')
GROUP BY f.facility_type ORDER BY f.facility_type;
SELECT COUNT(*) AS instalaciones_silver_en_regla, COUNT(DISTINCT f.name) AS nombres_silver_en_regla
FROM silver.facility f
WHERE f.facility_type IN ('military_base','national_lab','nuclear_test_site','test_range','nuclear_base');
SELECT table_name, COUNT(*) AS incidencias, COUNT(DISTINCT record_id) AS registros
FROM silver.quality_issue GROUP BY table_name ORDER BY table_name;

-- Perfil Silver para el cotejo de linaje, con recuentos de valores no nulos.
SELECT 'country_evidence' AS tabla, COUNT(*) AS filas,COUNT("table_name") AS "table_name",COUNT("record_id") AS "record_id",COUNT("reported_value") AS "reported_value",COUNT("coded_value") AS "coded_value",COUNT("reported_iso2") AS "reported_iso2",COUNT("coded_iso2") AS "coded_iso2" FROM silver."country_evidence";
